list_tax_country_taxes.code:
var response = await client.TaxCountryTaxes.ListTaxCountryTaxesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var countryTax in ((IReadOnlyList<object?>)body["country_taxes"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{countryTax["id"]} {countryTax["name"]} {countryTax["rate_display"]}");

create_tax_country_tax.code:
var response = await client.TaxCountryTaxes.CreateTaxCountryTaxAsync(new Dictionary<string, object?>
{
    ["country_tax"] = new Dictionary<string, object?>
    {
        ["country_code"] = "NZ", ["name"] = "New Zealand", ["tax_rate"] = 4.5, ["tax_method"] = "FIXED_RATE", ["is_default"] = false,
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var countryTax = (IReadOnlyDictionary<string, object?>)body["country_tax"]!;
Console.WriteLine(countryTax["id"]);

get_tax_country_tax.code:
var response = await client.TaxCountryTaxes.GetTaxCountryTaxAsync(4);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var countryTax = (IReadOnlyDictionary<string, object?>)body["country_tax"]!;
Console.WriteLine($"{countryTax["name"]} {countryTax["rate_display"]}");
foreach (var stateRule in ((IReadOnlyList<object?>)countryTax["state_rules"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{stateRule["id"]} {stateRule["tax_rule"]} {stateRule["effective_tax_rate"]}");

